namespace Altairis.Api.Entities;

// Lifecycle of a booking. Only Cancelled gives the nights back to the inventory:
// a no-show is still charged by the hotel, so its rooms stay counted as booked.
public enum ReservationStatus
{
    Confirmed,
    CheckedIn,
    CheckedOut,
    Cancelled,
    NoShow,
}

public class Reservation
{
    public int Id { get; set; }

    // Human-friendly reference ("ALT-1000123") for phone calls and emails.
    // Generated by a database sequence, so it's unique even under concurrent inserts and also
    // when rows are created by SQL scripts (the demo seed).
    // Null until saved, on purpose: if it were "" EF would think it's already set and insert the
    // empty string instead of letting the database generate it.
    public string Code { get; set; } = null!;

    // The room (hotel + room type) being booked. Hotel and type are reached through it,
    // not copied here, so there's a single source of truth.
    public int RoomId { get; set; }
    public Room Room { get; set; } = null!;

    // Hotel convention: the guest sleeps the nights [CheckIn, CheckOut). The check-out day
    // is not a night of the stay, so a 20 -> 23 stay uses the nights 20, 21 and 22.
    public DateOnly CheckIn { get; set; }
    public DateOnly CheckOut { get; set; }

    // Number of rooms of that type in the same booking (e.g. a family taking 2 Doubles).
    public int Rooms { get; set; }
    public int Guests { get; set; }

    public string GuestName { get; set; } = string.Empty;
    public string GuestEmail { get; set; } = string.Empty;
    public string? GuestPhone { get; set; }
    public string? Notes { get; set; }

    // Frozen when the booking is made (sum of each night's price x rooms). If the hotel changes
    // prices later, existing bookings keep the price the customer accepted.
    public decimal TotalPrice { get; set; }

    public ReservationStatus Status { get; set; } = ReservationStatus.Confirmed;

    public DateTime CreatedAt { get; set; }
    public string? CreatedBy { get; set; }
    public DateTime? CancelledAt { get; set; }

    public int Nights => CheckOut.DayNumber - CheckIn.DayNumber;
}
